// src/pages/Dashboard.jsx
import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import { getMyReports } from "../api/thesis";

const Dashboard = () => {
  const navigate = useNavigate();
  const [reports, setReports] = useState([]);

  useEffect(() => {
    const token = localStorage.getItem("access");

    if (!token) {
      navigate("/login");
      return;
    }

    getMyReports()
      .then(setReports)
      .catch(() => {
        localStorage.clear();
        navigate("/login");
      });
  }, [navigate]);

  return (
    <div style={{ padding: "40px", color: "#e5e7eb" }}>
      <h1 style={{ marginBottom: "20px" }}>My Dashboard</h1>

      {reports.length === 0 ? (
        <p>No uploads yet.</p>
      ) : (
        <table style={{ width: "100%", borderCollapse: "collapse" }}>
          <thead>
            <tr>
              <th align="left">File</th>
              <th>Plagiarism</th>
              <th>AI</th>
              <th>Status</th>
            </tr>
          </thead>
          <tbody>
            {reports.map((r) => (
              <tr key={r.id}>
                <td>{r.file.split("/").pop()}</td>
                <td align="center">{r.plagiarism_score}%</td>
                <td align="center">{r.ai_score}%</td>
                <td align="center">{r.status}</td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </div>
  );
};

export default Dashboard;
